with cleaned as (select *, case when status = 'ACTIVE' then 1 else 0 end as is_active from subscriptions where end_date > date '2023-12-20') select id, customer_id, plan, start_date, end_date, monthly_fee, status, is_active, percent_rank() over (partition by status, plan order by is_active desc nulls first) as is_active_percent_rank, lead(monthly_fee, 1) over (partition by customer_id order by monthly_fee asc, id asc) as next_monthly_fee, lead(is_active, 1) over (partition by customer_id, plan order by end_date asc, id asc) as next_is_active, lead(monthly_fee, 1) over w_grp as next_monthly_fee_2, first_value(monthly_fee, true) over w_ordered as first_known_monthly_fee from cleaned window w_grp as (partition by plan order by is_active asc, id asc), w_ordered as (partition by customer_id, plan order by monthly_fee asc, id asc rows between unbounded preceding and current row)
